use xiom.io;
mod school {
  pub mod students {
    pub type Student {
      name: Str;
      grade: Int;
    }

    pub fn promote(s: &mut Student) {
      s.grade += 1;
    }
  }

  pub mod courses {
    pub type Course {
      name: Str;
      enrolled: Int;
      capacity: Int;
    }

    pub fn is_full(c: &Course) -> Bool {
      c.enrolled >= c.capacity
    }
  }
}

fn main() -> Int {
  use school;
  let mut s = school.students.Student{ name: "Alex", grade: 9 };
  school.students.promote(&mut s);
  io.println(s.grade.to_str());
  let c = school.courses.Course{ name: "Math", enrolled: 25, capacity: 30 };
  io.println(school.courses.is_full(&c).to_str());
  return 0;
}
